import * as React from "react";
// This is a skeleton starter React component generated by Plasmic.
import { observer } from "mobx-react";
// Feel free to edit as you see fit.
import { clearDarkMask, createDarkMask } from "@/wab/client/components/darkMask";
import { useI18n } from "@/wab/client/i18n";
import { Alert, Button, Tooltip } from "antd";
import {
PlasmicAlertBanner,
PlasmicAlertBanner__VariantsArgs,
} from "@/wab/client/components/widgets/plasmic/PlasmicAlertBanner";
import { StudioCtx } from "@/wab/client/studio-ctx/StudioCtx";
import { assert } from "@/wab/shared/common";
import { APP_ROUTES } from "@/wab/shared/route/app-routes";
import { createPath } from "history";
import { useEffect } from "react";

export interface AlertData {
  stateVariant: PlasmicAlertBanner__VariantsArgs["state"];
  actionFn?: (studioCtx: StudioCtx) => Promise<void>;
}

export const AlertSpec = {
  ReadOnly: {
    stateVariant: "readOnly",
    actionFn: async (studioCtx: StudioCtx) => {
      const { projectId: newProjectId } =
        await studioCtx.appCtx.api.cloneProject(studioCtx.siteInfo.id);
      assert(window.top, "Unexpected null reference");
      window.top.location.href = APP_ROUTES.project.fill({
        projectId: newProjectId,
      });
    },
  },

  ConcurrentEdit: {
    stateVariant: "concurrentEdit",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  ViewOld: {
    stateVariant: "viewOld",
    actionFn: async (studioCtx: StudioCtx) => {
      // Passing in undefined means load latest
      await studioCtx.switchToBranchVersion(undefined);
    },
  },

  AuthError: {
    stateVariant: "authError",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  OutOfDate: {
    stateVariant: "outOfDate",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  Unlogged: {
    stateVariant: "unlogged",
    actionFn: async (studioCtx: StudioCtx) => {
      assert(window.top, "Unexpected null reference");
      window.top.location.href = APP_ROUTES.login.fill(
        {},
        { continueTo: createPath(studioCtx.appCtx.history.location) }
      );
    },
  },

  WelcomeGuest: {
    stateVariant: "welcomeGuest",
    actionFn: async (studioCtx: StudioCtx) => {
      assert(window.top, "Unexpected null reference");
      window.top.location.href = APP_ROUTES.login.fill(
        {},
        { continueTo: createPath(studioCtx.appCtx.history.location) }
      );
    },
  },

  PermError: {
    stateVariant: "permError",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  Watch: {
    stateVariant: "watch",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  InvariantError: {
    stateVariant: "invariantError",
    actionFn: async (studioCtx: StudioCtx) => {
      return studioCtx.appCtx.api.reloadLocation();
    },
  },

  ProtectedMainBranch: {
    stateVariant: "protectedMainBranch",
  },
} as const;

(window as any).alertspec = AlertSpec;

interface AlertBannerProps {
  studioCtx: StudioCtx;
}

export const AlertBanner = observer(function AlertBanner_({
  studioCtx,
}: AlertBannerProps) {
  const alertState = studioCtx.alertBannerState.get();
  const { t } = useI18n();
  const localConflict = alertState === AlertSpec.ConcurrentEdit && studioCtx.desktopDraft?.status?.state === "conflict";

  useEffect(() => {
    if (localConflict) {
      clearDarkMask();
    } else if (studioCtx.blockChanges && !studioCtx.isAtTip) {
      createDarkMask(studioCtx);
    }
  }, [studioCtx.blockChanges, studioCtx.isAtTip, localConflict]);

  // If no state defined, hide the element
  if (!alertState) {
    return <></>;
  }

  if (localConflict) {
    return <Alert type="warning" showIcon title={<Tooltip title={t("Local drafts are preserved on this device. Click to review them without replacing the remote project.")}><span>{t("Drafts need attention")}</span></Tooltip>}
      action={<Button size="small" onClick={() => { if (studioCtx.desktopDraft) {studioCtx.desktopDraft.dialogOpen = true;} }}>{t("Local drafts")}</Button>} />;
  }

  const actionFn = alertState.actionFn;
  return (
    <PlasmicAlertBanner
      root={{
        className: "over-dark-mask",
      }}
      variants={{ state: alertState.stateVariant }}
      overrides={{
        actionBtn: {
          onClick: actionFn ? () => actionFn(studioCtx) : undefined,
        },

        dismissBtn: {
          "data-test-id": "alert-banner-dismiss",
          onClick: (event) => {
            event.stopPropagation();
            studioCtx.alertBannerState.set(null);
          },
        } as any,

        watchBtn: {
          onClick: () => studioCtx.enterWatchMode(),
        },
      }}
    />
  );
});
